        }

    ) { innerPadding ->

        NavHost(
            navController = navController,
            startDestination = Routes.HOME,
            modifier = Modifier.padding(innerPadding)
        ) {

            composable(Routes.SPLASH) {
                SplashScreen()
            }

            composable(Routes.HOME) {

                HomeScreen(
                    viewModel = homeViewModel,

                    onNavigateToSong = { songId ->
                        navController.navigate("song/$songId")
                    }
                )
            }

            composable(Routes.SETTINGS) {

                SettingsScreen(
                    viewModel = settingsViewModel,

                    onNavigateToBluetooth = {
                        navController.navigate(Routes.BLUETOOTH)
                    }
                )
            }

            composable(
                route = Routes.SONG,
                arguments = listOf(
                    navArgument("songId") {
                        type = NavType.IntType
                    }
                )
            ) { backStackEntry ->

                val songId =
                    backStackEntry.arguments?.getInt("songId") ?: 0

                SongScreen(
                    songId = songId,
                    viewModel = songViewModel
                )
            }

            composable(Routes.BLUETOOTH) {

                BluetoothScreen(
                    viewModel = bluetoothViewModel
                )
            }
        }
    }
}

package com.example.harpapp.data

import androidx.room.TypeConverter

class Converters {
    @TypeConverter
    fun fromDifficulty(difficulty: Difficulty): String {
        return difficulty.name
    }

    @TypeConverter
    fun toDifficulty(value: String): Difficulty {
        return Difficulty.valueOf(value)
    }
}

package com.example.harpapp.data

import androidx.room.TypeConverter
