    }
}

package com.example.harpapp.data

import android.content.Context
import android.media.MediaMetadataRetriever

object MidiDurationHelper {
    fun getDurationMs(context: Context, midiFileName: String): Long {
        return try {
            val retriever = MediaMetadataRetriever()
            context.assets.openFd(midiFileName).use { afd ->
                retriever.setDataSource(afd.fileDescriptor, afd.startOffset, afd.length)
            }
            val durationStr = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)
            retriever.release()
            durationStr?.toLongOrNull() ?: 0L
        } catch (e: Exception) {
            e.printStackTrace()
            0L
        }
    }

    fun formatDuration(durationMs: Long): String {
        val totalSeconds = (durationMs / 1000).toInt()
        val minutes = totalSeconds / 60
        val seconds = totalSeconds % 60
        return "$minutes:${seconds.toString().padStart(2, '0')}"
    }
}

package com.example.harpapp.ui.components
import androidx.compose.material3.Icon import androidx.compose.material3.NavigationBar import androidx.compose.material3.NavigationBarItem import androidx.compose.material3.NavigationBarItemDefaults import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import com.example.harpapp.ui.theme.DarkRed import com.example.harpapp.ui.theme.MediumRed import com.example.harpapp.ui.theme.LightRed
@Composable fun NavBar( currentRoute: String?, onNavigate: (route: String) -> Unit, modifier: Modifier = Modifier, items: List<NavBarItem> = listOf( NavBarItem.Home, NavBarItem.Song, NavBarItem.Settings ), alwaysShowLabel: Boolean = false ) { NavigationBar( modifier = modifier, containerColor = DarkRed, contentColor = Color.White ) { items.forEach { item -> val selected = currentRoute?.let { cur -> cur == item.route || cur.startsWith(item.route) } ?: false
NavigationBarItem( icon = { Icon(item.icon, contentDescription = item.title) }, label = { Text(item.title) }, selected = selected, onClick = { if (!selected) onNavigate(item.route) }, alwaysShowLabel = alwaysShowLabel, colors = NavigationBarItemDefaults.colors( selectedIconColor = Color.White, selectedTextColor = Color.White, indicatorColor = MediumRed, unselectedIconColor = Color.White.copy(alpha = 0.7f), unselectedTextColor = Color.White.copy(alpha = 0.7f) ) ) } } }

package com.example.harpapp.ui.components
import androidx.compose.material3.Icon import androidx.compose.material3.NavigationBar import androidx.compose.material3.NavigationBarItem import androidx.compose.material3.NavigationBarItemDefaults import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import com.example.harpapp.ui.theme.DarkRed import com.example.harpapp.ui.theme.MediumRed import com.example.harpapp.ui.theme.LightRed
@Composable fun NavBar( currentRoute: String?, onNavigate: (route: String) -> Unit, modifier: Modifier = Modifier, items: List<NavBarItem> = listOf( NavBarItem.Home, NavBarItem.Song, NavBarItem.Settings ), alwaysShowLabel: Boolean = false ) { NavigationBar( modifier = modifier, containerColor = DarkRed, contentColor = Color.White ) { items.forEach { item -> val selected = currentRoute?.let { cur -> val baseRoute = item.route.substringBefore("/") cur == item.route || cur.startsWith(baseRoute) } ?: false
NavigationBarItem( icon = { Icon(item.icon, contentDescription = item.title) }, label = { Text(item.title) }, selected = selected, onClick = { if (!selected) onNavigate(item.route) }, alwaysShowLabel = alwaysShowLabel, colors = NavigationBarItemDefaults.colors( selectedIconColor = Color.White, selectedTextColor = Color.White, indicatorColor = MediumRed, unselectedIconColor = Color.White.copy(alpha = 0.7f), unselectedTextColor = Color.White.copy(alpha = 0.7f) ) ) } } }

